select #{bookdate,jdbcType=DATE} bookdate ,#{enddate,jdbcType=DATE} enddate ,pos.INVEST_VARIETY ,pos.trade_type ,pos.IS_UNDER_TRADE ,pos.ASSET_CODE ,pos.PROD_ID ,pos.chl_id chlid ,pos.CCY ,decode(pos.ASSET_CODE,'REMAININGCASH','01',info.asset_type) assettype ,decode(pos.ASSET_CODE,'REMAININGCASH','1001',info.ASSET_TYPE2) assettype2 ,nvl(nvl(info.PRO_INDUSTRY,info.INDUSTRY1),info.INDUSTRY_SHARES) INDUSTRY1 /*所属行业*/ ,info.IN_ASSET_TYPE IN_ASSET_TYPE /*行业一级分类*/ ,sum(pos.accuamt) ASSETVALUE_A /*穿透前资产价值*/ ,sum(decode(pos.trade_type,'05',pos.accuqty,null)) ASSETVALUE_B /*穿透后资产价值*/ ,nvl(bestRatingZx.GRADERESULT,bestRatingZt.GRADERESULT) rating/*债券评级*/ ,decode(info.PRIVATE_FLAG,'01','01',null) MONIT_TYPE ,decode(info.PPPFLAG,'01','01',null) PPPFLAG ,decode(info.IS_GOVERN_FUND,'01','01',null) IS_GOVERN_FUND1 ,decode(info.PRIVATEFUND_FLAG,'01','01',null) PRIVATEFUND_FLAG ,decode(info.PRIVATEPRD_FLAG,'01','01',null) PRIVATEPRD_FLAG ,decode(info.BONDTOSTOCK_FLAG,'01','01',null) BONDTOSTOCK_FLAG ,info.MANAGE_TYPE MANAGE_TYPE /*管理方式*/ from CHB_ASSET_POSITION pos left join CHB_ASSET_INFO info on pos.ASSET_CODE=info.ASSET_CODE and info.status !='D' left join CHB_PRD_BASEINFO prd on prd.PROD_ID=pos.PROD_ID and prd.status !='D'
left join ( select t.OCODE as OCODE,t.GRADERESULT as GRADERESULT FROM( SELECT TEMP.GRADERESULT as GRADERESULT, TEMP.OCODE AS OCODE, rank() over (partition by TEMP.OCODE order by rownum) rk FROM (
)
${getProductRatingOrderSqlByZx}
)t where t.rk = '1' )bestRatingZx on bestRatingZx.OCODE = pos.ASSET_CODE
left join( select t.OCODE as OCODE,t.GRADERESULT as GRADERESULT FROM( SELECT TEMP.GRADERESULT as GRADERESULT, TEMP.OCODE AS OCODE, rank() over (partition by TEMP.OCODE order by rownum) rk FROM(
)
${getProductRatingOrderSqlByZt}
)t where t.rk = '1' )bestRatingZt on bestRatingZt.OCODE = info.FINANCIE where 1=1 and prd.PROFIT_TYPE='03' /****资产负债表中1.9.5统计错误***/ and (info.PBC_ASSET_TYPE3 NOT IN('J03','J04') or info.PBC_ASSET_TYPE3 is null) and pos.trade_type in ('01','02','05') /*直投交易,通道交易,资管计划交易*/ and pos.cDATE =#{enddate,jdbcType=DATE} group by #{bookdate,jdbcType=DATE},#{enddate,jdbcType=DATE}, pos.INVEST_VARIETY,pos.trade_type,pos.IS_UNDER_TRADE, pos.ASSET_CODE, pos.PROD_ID, pos.chl_id, pos.CCY, decode(pos.ASSET_CODE,'REMAININGCASH','01',info.asset_type), decode(pos.ASSET_CODE,'REMAININGCASH','1001',info.ASSET_TYPE2), nvl(nvl(info.PRO_INDUSTRY,info.INDUSTRY1),info.INDUSTRY_SHARES),info.IN_ASSET_TYPE, null,nvl(bestRatingZx.GRADERESULT,bestRatingZt.GRADERESULT), decode(info.PRIVATE_FLAG,'01','01',null), decode(info.PPPFLAG,'01','01',null), decode(info.IS_GOVERN_FUND,'01','01',null), decode(info.PRIVATEFUND_FLAG,'01','01',null), decode(info.PRIVATEPRD_FLAG,'01','01',null), decode(info.BONDTOSTOCK_FLAG,'01','01',null), info.MANAGE_TYPE

